// selectKubeClusterEndpoint selects and records one kube_service endpoint for
// the lifetime of the session.
func (s *clusterSession) selectKubeClusterEndpoint() (kubeClusterEndpoint, error) {
	s.endpointMu.Lock()
	defer s.endpointMu.Unlock()

	if len(s.teleportClusterEndpoints) == 0 {
		return kubeClusterEndpoint{}, trace.BadParameter("no endpoints to dial")
	}
	if s.selectedEndpoint == nil {
		selected := s.teleportClusterEndpoints[mathrand.Intn(len(s.teleportClusterEndpoints))]
		s.selectedEndpoint = &selected
		s.kubeAddress = selected.addr
		s.teleportCluster.targetAddr = selected.addr
		s.teleportCluster.serverID = selected.serverID
	}
	return *s.selectedEndpoint, nil
}

// dial opens a connection to the selected kube_service endpoint.
func (s *clusterSession) dial(ctx context.Context, network string) (net.Conn, error) {
	endpoint, err := s.selectKubeClusterEndpoint()
	if err != nil {
		return nil, trace.Wrap(err)
	}
	return s.teleportCluster.dialEndpoint(ctx, network, endpoint)
}

