1512	func (f *Forwarder) newClusterSessionSameCluster(ctx authContext) (*clusterSession, error) {
1513		if ctx.kubeCluster == "" {
1514			return nil, trace.NotFound("kubernetes cluster name is not specified")
1515		}
1516		if _, ok := f.creds[ctx.kubeCluster]; ok {
1517			return f.newClusterSessionLocal(ctx)
1518		}
1519	
1520		kubeServices, err := f.cfg.CachingAuthClient.GetKubeServices(f.ctx)
1521		if err != nil && !trace.IsNotFound(err) {
1522			return nil, trace.Wrap(err)
1523		}
1524	
1525		if len(kubeServices) == 0 && ctx.kubeCluster == ctx.teleportCluster.name {
1526			return f.newClusterSessionLocal(ctx)
1527		}
1528	
1529		// Validate that the requested kube cluster is registered.
1530		var endpoints []endpoint
1531	outer:
1532		for _, s := range kubeServices {
1533			for _, k := range s.GetKubernetesClusters() {
1534				if k.Name != ctx.kubeCluster {
1535					continue
1536				}
1537				// TODO(awly): check RBAC
